import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_max_dim1(torch::Tensor x);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math_constants.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void cute_max_dim1_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    int B,
    int D1,
    int D2)
{
    const int col = blockIdx.x * blockDim.x + threadIdx.x;
    const int batch = blockIdx.y;

    if (batch >= B || col >= D2) {
        return;
    }

    auto gX = make_tensor(
        make_gmem_ptr(x),
        make_shape(B, D1, D2),
        make_stride(D1 * D2, D2, Int<1>{}));

    auto gO = make_tensor(
        make_gmem_ptr(out),
        make_shape(B, D2),
        make_stride(D2, Int<1>{}));

    float acc = -CUDART_INF_F;

    for (int k = 0; k < D1; ++k) {
        const float value = gX(batch, k, col);

        // Match torch.max behavior for NaNs by propagating them.
        if (value != value || value > acc) {
            acc = value;
        }
    }

    gO(batch, col) = acc;
}


torch::Tensor cute_max_dim1(torch::Tensor x)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 3, "x must be a 3D tensor");
    TORCH_CHECK(
        x.scalar_type() == at::kFloat,
        "cute_max_dim1 currently supports float32 tensors only");

    const int B = static_cast<int>(x.size(0));
    const int D1 = static_cast<int>(x.size(1));
    const int D2 = static_cast<int>(x.size(2));

    auto x_contiguous = x.contiguous();
    auto out = torch::empty({B, D2}, x.options());

    constexpr int threads = 256;
    dim3 block(threads);
    dim3 grid(
        (D2 + threads - 1) / threads,
        B);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_max_dim1_kernel<<<grid, block, 0, stream>>>(
        x_contiguous.data_ptr<float>(),
        out.data_ptr<float>(),
        B,
        D1,
        D2);

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "cute_max_dim1_kernel launch failed");

    return out;
}
"""


cute_ext = load_inline(
    name="cute_max_dim1_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_max_dim1"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        if dim < 0:
            dim += 3
        if dim != 1:
            raise ValueError("ModelNew supports reduction over dimension 1")
        self.dim = dim
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_max_dim1(x)

